1	/**
2	 * @module ProtectedRoute
3	 *
4	 * Guarda de rota para usuários não autenticados, desativados ou pendentes.
5	 * Redireciona para `/auth` se não houver sessão ativa, bloqueia contas
6	 * desativadas e exibe tela de aprovação pendente quando necessário.
7	 */
8	
9	import { useAuth } from '@/shared/hooks/useAuth';
10	import { Navigate } from 'react-router-dom';
11	import ApprovalPending from './ApprovalPending';
12	import { useEffect, useState } from 'react';
13	import { Button } from '@/shared/ui/button';
14	import { ShieldX, LogOut } from 'lucide-react';
15	
16	interface ProtectedRouteProps {
17	  children: React.ReactNode;
18	}
19	
20	/**
21	 * Tela exibida quando a conta do usuário foi desativada por um administrador.
22	 */
23	function AccountDeactivated({ onSignOut }: { onSignOut: () => void }) {
24	  return (
25	    <div className="min-h-screen flex items-center justify-center bg-background px-4">
26	      <div className="max-w-md w-full text-center space-y-6">
27	        <div className="mx-auto w-16 h-16 rounded-full bg-red-100 dark:bg-red-900/20 flex items-center justify-center">
28	          <ShieldX className="w-8 h-8 text-red-600 dark:text-red-400" />
29	        </div>
30	        <div className="space-y-2">
31	          <h1 className="text-2xl font-bold text-foreground">Conta Desativada</h1>
32	          <p className="text-muted-foreground">
33	            Sua conta foi desativada por um administrador.
34	            Entre em contato com a gerência para reativar seu acesso.
35	          </p>
36	        </div>
37	        <Button data-mia-action="sign-out"
38	          variant="outline"
39	          className="gap-2"
40	          onClick={onSignOut}
41	        >
42	          <LogOut className="w-4 h-4" />
43	          Sair
44	        </Button>
45	      </div>
46	    </div>
47	  );
48	}
49	
50	/**
51	 * Protege rotas contra acesso não autenticado.
52	 * Exibe spinner durante verificação, redireciona para `/auth` se sem sessão,
53	 * bloqueia contas desativadas e mostra tela de aprovação pendente.
54	 *
55	 * @param children - Conteúdo da rota protegida.
56	 */
57	export function ProtectedRoute({ children }: ProtectedRouteProps) {
58	  const { user, userProfile, loading, needsApproval, signOut } = useAuth();
59	  const [isInitialized, setIsInitialized] = useState(false);
60	
61	  useEffect(() => {
62	    // Marcar como inicializado após o primeiro ciclo de loading
63	    if (!loading) {
64	      setIsInitialized(true);
65	    }
66	  }, [loading]);
67	
68	  // Mostrar loading apenas se ainda não foi inicializado ou está carregando
69	  if (loading || !isInitialized) {
70	    return (
71	      <div className="min-h-screen flex items-center justify-center bg-background">
72	        <div className="flex flex-col items-center space-y-4">
73	          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
74	          <p className="text-muted-foreground">Verificando autenticação...</p>
75	        </div>
76	      </div>
77	    );
78	  }
79	
80	  // Redirecionar para login se não há usuário
81	  if (!user) {
82	    return <Navigate to="/auth" replace />;
83	  }
84	
85	  // Conta desativada — bloquear acesso
86	  if (userProfile && userProfile.ativo === false) {
87	    return <AccountDeactivated onSignOut={signOut} />;
88	  }
89	
90	  // Se o usuário precisa de aprovação, mostrar tela de aprovação
91	  if (needsApproval && userProfile) {
92	    return (
93	      <ApprovalPending
94	        userProfile={{
95	          nome: userProfile.nome,
96	          username: userProfile.username,
97	          created_at: userProfile.created_at,
98	        }}
99	      />
100	    );
101	  }
102	
103	  return <>{children}</>;
104	}
